/** A refund of a payment */
export const RefundSchema = v.pipe(v.strictObject({ refund_id: RefundIdSchema, payment_id: PaymentIdSchema, merchant_id: MerchantIdSchema, amount: AmountSchema, currency: CurrencySchema, captured_amount: CapturedAmountSchema, refunded_total: RefundedTotalSchema, created_at: CreatedAtSchema }, 'Must be an object'),
  $rule("refund", "refunds_within_captured", "The refunds of a payment must not exceed the captured amount", (value: any) => $and(() => (((value as any)["amount"] as any) <= ((value as any)["refunded_total"] as any)), () => (((value as any)["refunded_total"] as any) <= ((value as any)["captured_amount"] as any)))));

