/** Checks a value against a definition: its structure, then each rule. */
export function check<D extends DefinitionName>(definition: D, value: unknown): CheckResult<DefinitionTypes[D]> {
  const failures: Failure[] = [];
  return CHECKS[definition](value, '', failures) ? { ok: true, domain: DOMAIN, value: value as DefinitionTypes[D] } : { ok: false, domain: DOMAIN, failures };
}

/** What an operation answers: one of its outputs, by name, and its value. */
export interface Answer<O extends string, V> {
  readonly output: O;
  readonly value: V;
}

/** An answer of the core: answer('booking', booking). */
export function answer<O extends string, V>(output: O, value: V): Answer<O, V> {
  return { output, value };
}

/** The answers of create_payment. */
export type CreatePaymentAnswer = Answer<"payment_changed", PaymentChanged> | Answer<"invalid_request", InvalidRequest> | Answer<"card_declined", CardDeclined> | Answer<"insufficient_funds", InsufficientFunds> | Answer<"expired_card", ExpiredCard> | Answer<"fraud_suspected", FraudSuspected> | Answer<"unsupported_currency", UnsupportedCurrency> | Answer<"idempotency_conflict", IdempotencyConflict> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"unauthorized", Unauthorized>;

/** The answers of capture_payment. */
export type CapturePaymentAnswer = Answer<"payment_changed", PaymentChanged> | Answer<"capture_exceeds_authorized", CaptureExceedsAuthorized> | Answer<"invalid_state", InvalidState> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"unauthorized", Unauthorized>;

/** The answers of void_payment. */
export type VoidPaymentAnswer = Answer<"payment_changed", PaymentChanged> | Answer<"invalid_state", InvalidState> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"unauthorized", Unauthorized>;

/** The answers of expire_payment. */
export type ExpirePaymentAnswer = Answer<"payment_changed", PaymentChanged> | Answer<"invalid_state", InvalidState> | Answer<"forbidden", Forbidden> | Answer<"unauthorized", Unauthorized>;

/** The answers of settle_payment. */
export type SettlePaymentAnswer = Answer<"payment_changed", PaymentChanged> | Answer<"invalid_state", InvalidState> | Answer<"forbidden", Forbidden> | Answer<"unauthorized", Unauthorized>;

/** The answers of get_payment. */
export type GetPaymentAnswer = Answer<"payment", Payment> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"unauthorized", Unauthorized>;

/** The answers of refund_payment. */
export type RefundPaymentAnswer = Answer<"refund_made", RefundMade> | Answer<"amount_exceeds_captured", AmountExceedsCaptured> | Answer<"refund_window_closed", RefundWindowClosed> | Answer<"invalid_state", InvalidState> | Answer<"idempotency_conflict", IdempotencyConflict> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"unauthorized", Unauthorized>;

/** The answers of get_refund. */
export type GetRefundAnswer = Answer<"refund", Refund> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"unauthorized", Unauthorized>;

/** The core: a function for each operation, from its input to one of its answers. */
export interface DomainCore {
  /** Create a payment and ask the buyer's bank to authorize it */
  readonly create_payment: (input: CreatePaymentRequest) => CreatePaymentAnswer;
  /** Capture an authorized payment, in full or in part */
  readonly capture_payment: (input: CaptureRequest) => CapturePaymentAnswer;
  /** Cancel an authorized payment that was not captured */
  readonly void_payment: (input: VoidRequest) => VoidPaymentAnswer;
  /** Expire an authorized card payment that was not captured within 7 days of its authorization */
  readonly expire_payment: (input: Expiry) => ExpirePaymentAnswer;
  /** Authorize a pending bank transfer payment whose money arrived, or fail one whose transfer failed */
  readonly settle_payment: (input: Settlement) => SettlePaymentAnswer;
  /** Read a payment by its id */
  readonly get_payment: (input: PaymentLookup) => GetPaymentAnswer;
  /** Give back a part or all of a captured payment */
  readonly refund_payment: (input: RefundRequest) => RefundPaymentAnswer;
  /** Read a refund by its id */
  readonly get_refund: (input: RefundLookup) => GetRefundAnswer;
}

